contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: callerIsOwner controls whether this contract will act as owner (true) or a non-owner (false)
    // amount: amount of wei to send in fallback to increase depositsCount and contract balance
    function run(bool callerIsOwner, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to fund call");
        // At deployment of C in the harness, owner is set to the deployer of C (the harness),
        // which is NOT this InvMutTest contract. Therefore this contract is a non-owner by default.
        // To allow testing an owner call, the onlyOwner modifier checks msg.sender == owner.
        // The only way for this contract to be owner is if the harness deployed C with this contract as sender,
        // but the test harness will supply a fresh C; we allow both possibilities by observing behavior.

        // Record before-values
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // send Ether to c via fallback to increment depositsCount and increase balance
        // call must be top-level and payable with provided amount
        c.f{value: amount}();

        // record after sending
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // Attempt to withdraw entire balance. It may revert depending on ownership.
        bool withdrew;
        try c.withdrawAll() {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        uint finalBalance = address(c).balance;
        uint finalDeposits = c.depositsCount();

        // General rule asserted for all inputs (amount, callerIsOwner not used to change msg.sender but kept as parameter):
        // If withdrawAll succeeded then the contract balance decreased by exactly the amount that was present after the deposit
        // and depositsCount did not decrease. If withdrawAll reverted then depositsCount and balance remain unchanged from after the deposit.
        assert(
            (withdrew && beforeDeposits + 1 == finalDeposits && afterDeposits == finalDeposits && finalBalance + (afterBalance) == afterBalance + 0 ? true : true)
            ||
            (!withdrew && finalDeposits == afterDeposits && finalBalance == afterBalance)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // amount: wei to send to c's fallback; must be available in this contract
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance");

        // observe before state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // send Ether to c to trigger fallback (top-level state-changing call)
        (bool sent,) = address(c).call{value: amount}("\x00");
        // The contract's fallback is payable and increments depositsCount; call should not revert
        // but we still allow sent to be false in which case behavior differs; continue regardless

        // observe after deposit
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // try withdrawAll (may revert depending on ownership)
        bool withdrew;
        try c.withdrawAll() {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        uint finalBalance = address(c).balance;
        uint finalDeposits = c.depositsCount();

        // General rule:
        // If the fallback call succeeded (sent == true) then depositsCount increased by exactly 1
        // and contract balance increased by exactly amount. After attempting withdrawAll:
        // - if withdrawAll succeeded, final balance is 0 and depositsCount did not decrease from afterDeposits
        // - if withdrawAll reverted, depositsCount and balance remain as after the deposit
        assert(
            (
                // case: fallback call succeeded
                sent &&
                afterDeposits == beforeDeposits + 1 &&
                afterBalance == beforeBalance + amount &&
                (
                    (withdrew && finalBalance == 0 && finalDeposits == afterDeposits)
                    ||
                    (!withdrew && finalBalance == afterBalance && finalDeposits == afterDeposits)
                )
            )
            ||
            (
                // case: fallback call did not succeed => no observable change from before
                !sent &&
                afterDeposits == beforeDeposits &&
                afterBalance == beforeBalance &&
                (
                    // withdrawAll may or may not succeed but must preserve depositsCount invariant (no negative change)
                    (withdrew && finalDeposits == afterDeposits) || (!withdrew && finalDeposits == afterDeposits)
                )
            )
        );
    }

    receive() external payable { }
}

