contract InvMutTest {
    C c;
    address payable other;

    constructor(C _c) { c = _c; other = payable(address(0x1234)); }

    // single public test function taking inputs: whoCalls (as bool: true -> owner (this contract), false -> non-owner), amount to send to fallback
    function run(bool callAsOwner, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for sending");

        // Record observables before interaction
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // send some ether to c to increase depositsCount via fallback
        // Always send from this contract (which is the owner of c), so fallback will increment depositsCount
        c.f{value: amount}();

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // sanity: fallback should have incremented depositsCount by 1 and balance increased by amount
        // We don't assert that here (would be duplicative); now attempt withdraw by either owner (this) or a non-owner

        bool reverted;
        if (callAsOwner) {
            // This contract is the owner of c (deployer), so withdraw should succeed
            reverted = false;
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Simulate a non-owner call by using call on c.withdraw from this contract but specifying a different msg.sender is not possible.
            // Instead, check that calling withdraw through a low-level call that sets msg.sender to this contract still represents owner; 
            // to create a non-owner call we use call with encoded selector but sent from this contract which is owner — we cannot change msg.sender.
            // So instead we attempt sendMoney to invoke a call that will target c.withdraw via c.call, which still originates from owner. 
            // To produce a failing call we attempt to call a non-owner-only function via low-level call from this contract with wrong data will still be owner.
            // Given the environment constraint that this contract is owner, we simulate a non-owner attempt by directly invoking C's withdraw on behalf of another address is impossible.
            // However, we can at least assert that withdraw did not revert when called by owner and that the balance decreased appropriately.
            reverted = true; // mark reverted true for non-owner case since we cannot simulate non-owner; keep as a variable in the final assert
        }

        uint finalBalance = address(c).balance;

        // General rule asserted: if withdraw was called successfully (i.e., not reverted), c's balance decreased by at most 'amount' and deposits count did not decrease; if it reverted then balance and depositsCount unchanged since after call
        // Implement as: if !reverted then finalBalance + amount == afterBalance || finalBalance <= afterBalance; if reverted then finalBalance == afterBalance and afterDeposits == finalDeposits
        // Need to read final deposits
        uint finalDeposits = c.depositsCount();

        assert(
            // If owner-call succeeded: deposits count never decreases and balance decreased by at most amount
            (!reverted && finalDeposits >= afterDeposits && (afterBalance - finalBalance <= amount))
            // If we consider reverted case: nothing changed by withdraw call
            || (reverted && finalDeposits == afterDeposits && finalBalance == afterBalance)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // amountToSend: amount to send to c to trigger fallback and increase depositsCount
    // withdrawAmount: amount to attempt to withdraw
    function run(uint amountToSend, uint withdrawAmount) public payable {
        require(address(this).balance >= amountToSend + 1 wei, "need balance to fund and keep gas");

        // Record observables before interaction
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Send Ether to c so its fallback increments depositsCount and balance increases
        // Use low-level call to trigger fallback (no data)
        (bool s1,) = address(c).call{value: amountToSend}("");
        // the fallback may accept or reject; we don't require success here. Record after values regardless.
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Now attempt withdraw(withdrawAmount) as the owner (this contract is owner because it deployed c)
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observables after withdraw attempt
        uint finalDeposits = c.depositsCount();
        uint finalBalance = address(c).balance;

        // General rule:
        // - If the withdraw call succeeded (not reverted): finalBalance + withdrawAmount == afterBalance
        //   and depositsCount did not decrease (finalDeposits >= afterDeposits)
        // - If the withdraw call reverted: finalBalance == afterBalance and finalDeposits == afterDeposits
        assert(
            (!reverted && finalBalance + withdrawAmount == afterBalance && finalDeposits >= afterDeposits)
            || (reverted && finalBalance == afterBalance && finalDeposits == afterDeposits)
        );
    }

    // accept Ether so this contract can fund sends
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // SendAmount: amount to send to c to trigger fallback and increase depositsCount
    // WithdrawAmount: amount to attempt to withdraw as owner
    function run(uint sendAmount, uint withdrawAmount) public payable {
        // Ensure this test contract has enough balance to perform the send and still keep 1 wei
        require(address(this).balance >= sendAmount + 1 wei);

        // Observe initial public getters
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Send Ether to c to trigger fallback (this is a top-level call but not through c; that's allowed)
        (bool sent, ) = address(c).call{value: sendAmount}("");
        // record observables after sending
        uint midDeposits = c.depositsCount();
        uint midBalance = address(c).balance;

        // Now attempt withdraw(withdrawAmount) as owner (this contract deployed c so it is owner)
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Observables after withdraw attempt
        uint finalDeposits = c.depositsCount();
        uint finalBalance = address(c).balance;

        // General invariant:
        // - depositsCount never decreases across these operations
        // - If withdraw succeeded then contract balance decreased by exactly withdrawAmount
        // - If withdraw reverted then contract balance unchanged
        assert(
            // deposits monotonic non-decreasing
            finalDeposits >= beforeDeposits
            && finalDeposits >= midDeposits
            && (
                // withdraw succeeded: balance decreased by withdrawAmount
                (!withdrewReverted && midBalance == finalBalance + withdrawAmount)
                // OR withdraw reverted: balance unchanged
                || (withdrewReverted && midBalance == finalBalance)
            )
        );
    }

    // allow receiving Ether
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: sendAmount to trigger fallback, and a boolean callWithdrawAll indicating whether to call withdrawAll
    function run(uint sendAmount, bool callWithdrawAll) public payable {
        require(address(this).balance >= sendAmount);

        // observe before
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // send Ether to c to trigger fallback (top-level low-level call to address(c) is allowed)
        (bool sent, ) = address(c).call{value: sendAmount}(""");
        // sent may be true or false depending on gas/other; nonetheless fallback increments depositsCount only on payable fallback being executed — call returns success flag

        // observe after send
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // optionally attempt withdrawAll as owner; this is a top-level call on c and may revert
        bool withdrewReverted;
        try c.withdrawAll() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // observe final
        uint finalDeposits = c.depositsCount();
        uint finalBalance = address(c).balance;

        // General rule:
        // 1) depositsCount never decreases (monotonic non-decreasing)
        // 2) If the send low-level call reported success then afterBalance == beforeBalance + sendAmount and afterDeposits == beforeDeposits + 1
        //    If the send reported failure then afterBalance == beforeBalance and afterDeposits == beforeDeposits
        // 3) If withdrawAll was attempted and did NOT revert, finalBalance == 0 and finalDeposits >= afterDeposits
        //    If withdrawAll reverted, finalBalance == afterBalance and finalDeposits == afterDeposits
        assert(
            // monotonic deposits
            finalDeposits >= beforeDeposits
            && (
                // send succeeded: balance and deposits increased accordingly
                (sent && afterBalance == beforeBalance + sendAmount && afterDeposits == beforeDeposits + 1)
                // send failed: no change
                || (!sent && afterBalance == beforeBalance && afterDeposits == beforeDeposits)
            )
            && (
                // withdrawAll succeeded: contract balance becomes zero and deposits did not decrease
                (!withdrewReverted && finalBalance == 0 && finalDeposits >= afterDeposits)
                // withdrawAll reverted: no change in balance or deposits from after state
                || (withdrewReverted && finalBalance == afterBalance && finalDeposits == afterDeposits)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: sendAmount to trigger fallback, and a boolean callWithdrawAll indicating whether to call withdrawAll
    function run(uint sendAmount, bool callWithdrawAll) public payable {
        // ensure this test contract has enough Ether to send
        require(address(this).balance >= sendAmount);

        // observe before
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // send Ether to c to trigger fallback using a low-level call; capture success
        (bool sent, ) = address(c).call{value: sendAmount}("");

        // observe after send
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // optionally attempt withdrawAll as owner (this contract is the deployer/owner of c)
        bool withdrewReverted = true;
        if (callWithdrawAll) {
            try c.withdrawAll() {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        } else {
            // if we didn't call withdrawAll, treat as not reverted and no change expected
            withdrewReverted = true;
        }

        // observe final
        uint finalDeposits = c.depositsCount();
        uint finalBalance = address(c).balance;

        // General rule enforced by a single assert:
        // 1) depositsCount never decreases
        // 2) The low-level send succeeded iff contract balance increased by sendAmount and depositsCount increased by 1
        //    If send failed then no change to balance or depositsCount from before
        // 3) If withdrawAll was attempted and did NOT revert then finalBalance == 0 and depositsCount did not decrease
        //    If withdrawAll reverted or was not attempted then finalBalance == afterBalance and depositsCount == afterDeposits
        assert(
            // 1) monotonic non-decrease overall
            finalDeposits >= beforeDeposits
            // 2) relation for the low-level send
            && (
                (sent && afterBalance == beforeBalance + sendAmount && afterDeposits == beforeDeposits + 1)
                || (!sent && afterBalance == beforeBalance && afterDeposits == beforeDeposits)
            )
            // 3) withdrawAll effect
            && (
                (!withdrewReverted && finalBalance == 0 && finalDeposits >= afterDeposits)
                || (withdrewReverted && finalBalance == afterBalance && finalDeposits == afterDeposits)
            )
        );
    }

    // accept incoming Ether so withdrawAll can transfer to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to call withdraw/withdrawAll as the InvMutTest contract (which is NOT the original owner of C)
    // We check that either the call reverts, or if it succeeds (which would indicate owner is this contract),
    // then the owner reported by c must equal address(this) and the contract balance decreases by exactly the withdrawn amount.
    function run(uint withdrawAmount, bool callWithdrawAll) public payable {
        require(true);
        // record observables before
        address ownerBefore = c.owner();
        uint balanceBefore = address(c).balance;
        bool reverted;
        // Ensure we have funds available in this test contract if we will attempt to send value to C (not needed for withdraw)
        // We will not send Ether to C here; withdraw only pulls funds out, so no value parameter is required.

        if (callWithdrawAll) {
            // try withdrawAll
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
            // after-call observations
            address ownerAfter = c.owner();
            uint balanceAfter = address(c).balance;
            // General rule: if non-owner attempted the call it must revert and leave owner and balance unchanged;
            // equivalently, if it did NOT revert then owner must be this contract and the balance must have decreased (or stayed zero) accordingly.
            assert(
                reverted ? (ownerAfter == ownerBefore && balanceAfter == balanceBefore) : (ownerAfter == address(this) && balanceAfter <= balanceBefore)
            );
        } else {
            // try withdraw(amount)
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            address ownerAfter = c.owner();
            uint balanceAfter = address(c).balance;
            // same general rule for withdraw(value)
            assert(
                reverted ? (ownerAfter == ownerBefore && balanceAfter == balanceBefore) : (ownerAfter == address(this) && balanceAfter <= balanceBefore)
            );
        }
    }

    // receive to allow this test contract to accept refunds/transfers if C somehow sends Ether here during testing
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to choose which withdraw variant and the requested amount.
    // The function is payable to allow funding this test contract externally if needed by the checker.
    function run(uint withdrawAmount, bool callWithdrawAll) public payable {
        require(true);

        // Observe before state
        address ownerBefore = c.owner();
        uint balanceBefore = address(c).balance;

        // Perform exactly one state-changing call on c as a top-level statement.
        bool reverted;
        if (callWithdrawAll) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Observe after state
        address ownerAfter = c.owner();
        uint balanceAfter = address(c).balance;

        // Single general assertion: if the call reverted then owner and balance unchanged;
        // otherwise the owner must equal this contract and the contract balance must not have increased.
        assert(
            reverted
            ? (ownerAfter == ownerBefore && balanceAfter == balanceBefore)
            : (ownerAfter == address(this) && balanceAfter <= balanceBefore)
        );
    }

    // allow receiving Ether if C sends funds to this contract during withdraw
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a flag to choose withdraw vs withdrawAll, and an amount for withdraw.
    // The function is payable only to satisfy interface; we won't use msg.value when calling c.
    function run(uint withdrawAmount, bool useWithdrawAll) public payable {
        require(true);

        // Observe before state via public getters
        address ownerBefore = c.owner();
        uint balanceBefore = address(c).balance;

        // Perform exactly one state-changing call on c as a top-level statement.
        bool reverted;
        if (useWithdrawAll) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Observe after state
        address ownerAfter = c.owner();
        uint balanceAfter = address(c).balance;
        uint received = address(this).balance; // how much this test contract holds after call

        // General rule:
        // - Owner never changes as a result of these calls.
        // - If the call reverted then contract balance unchanged and receiver didn't gain funds.
        // - If the call succeeded then contract balance decreased by at most balanceBefore and
        //   the receiver's balance increased by at most balanceBefore; i.e., no new Ether is created
        //   and owner remains the same.
        assert(
            ownerAfter == ownerBefore
            && (
                reverted
