    // Params:
    //   fundFallback: amount of wei to send to C to trigger its fallback (increments depositsCount and increases C balance)
    // Precondition: this contract must have enough balance to fund C.
    function run(uint fundFallback) public payable {
        require(address(this).balance >= fundFallback, "insufficient balance for funding");

        // Record balances before funding
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Trigger fallback by sending empty calldata and fundFallback wei
        (bool funded, ) = address(c).call{value: fundFallback}("");

        // Ensure funding low-level call succeeded (otherwise C's balance didn't change)
        // We don't revert on failure of the low-level call; the assertion below will relate observed balances.

        // Now, as owner (this contract deployed c), call withdrawAll and capture whether it reverts.
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Observed balances after withdrawAll
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // The general rule to assert:
        // If withdrawAll did not revert, it must have transferred all of C's balance that existed immediately
        // before the withdrawAll call to the owner (this contract). Thus afterThis - beforeThis == amountWithdrawn
        // and afterC == 0. The amountWithdrawn must equal the C balance just before the withdrawAll call,
        // which is observed as beforeC + (funded ? fundFallback : 0).
        uint expectedCBeforeWithdraw = beforeC + (funded ? fundFallback : 0);

