            // so we require that either withdrawAll reverted, or (it didn't revert and exact transfer happened)
            withdrawAllReverted || (
                !withdrawAllReverted
                && afterC == 0
                && afterThis >= beforeThis // avoid underflow issues
                && afterThis - beforeThis == expectedCBeforeWithdraw
            )
        );
    }

    // Allow receiving ETH from C.withdraw
    receive() external payable { }
}

