    function run(uint8 mode, uint amount) public payable {
        require(mode <= 1);
        // ensure this contract has enough balance to forward amount when needed
        if (amount > 0) require(address(this).balance >= amount);

        // record observable before-values
        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        // perform exactly one top-level state-changing call on c
        bool reverted;
        if (mode == 0) {
            // trigger fallback by sending Ether to c
            reverted = false;
            try c.f{value: amount}() {
                // unreachable because fallback has no name; using try to catch revert if any
            } catch {
                reverted = true;
            }
        } else {
            // first fund c by sending amount (to create effect), then call withdrawAll()
            // top-level send to fallback
            reverted = false;
            try c.f{value: amount}() {
            } catch {
                reverted = true;
            }
            // perform owner-only withdrawAll() as separate top-level call
            bool reverted2;
            try c.withdrawAll() {
                reverted2 = false;
            } catch {
                reverted2 = true;
            }
            // combine revert flags: we require the sequence to have finished (we allow withdrawAll to revert or succeed)
            reverted = reverted || reverted2;
        }

        // read after-values
        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();

