        // - If the attempted Ether-send to c did not revert, depositsCount increases by exactly 1 and c's balance increases by amount.
        // - If the send reverted, neither depositsCount nor the balance change because of that send.
        // - Additionally, any withdrawAll() call (if executed) cannot increase depositsCount.
        bool sendSucceeded = (balAfter >= balBefore) ? (balAfter - balBefore == amount) : false;

        assert(
            // depositsCount change matches whether send succeeded: +1 exactly when sendSucceeded, else unchanged
            ((sendSucceeded && depositsAfter == depositsBefore + 1) || (!sendSucceeded && depositsAfter == depositsBefore))
            // and balance change equals amount when send succeeded, else unchanged
            && ((sendSucceeded && balAfter == balBefore + amount) || (!sendSucceeded && balAfter == balBefore))
            // and withdrawAll (if called) did not increase depositsCount
            && (depositsAfter >= depositsBefore)
        );
    }

