    // To get a non-owner call, we exploit that the C contract's owner was set to msg.sender at its construction (which was the deployer of C).
    // Since the checker deploys a fresh C and passes it into our constructor, our contract is the owner. To test non-owner behavior,
    // we use the fact that C only allows owner to call withdraw: sending a raw call with data to c from this contract still has msg.sender == address(this).
    // So to observe a revert for non-owner we instead call c.sendMoney targeting c itself with some value and data that will cause c to revert when not owner.
    // However sendMoney is onlyOwner too. We can observe that fallback increments depositsCount when contract receives plain ether.
    // Our invariant: Only owner can decrease address(c).balance via withdraw/withdrawAll; any call from this contract that is not owner cannot decrease balance.

    // Because we cannot change who is owner (it's this contract), we test two behaviours:
    // - After sending some ether into c (via fallback by calling with empty data), calling withdraw(amount) by owner decreases address(c).balance by exactly amount (unless amount > balance then it sends 0 or reverts?).
    // - Calling withdraw with amount > previous balance should still transfer at most the balance; but C.withdraw uses transfer which will revert if _value > balance? Actually transfer sends value and will revert if not enough balance.
    // To make a clear general rule we require amount <= address(c).balance before calling withdraw.

    // Therefore parameters: uint depositAmount (to send into c), uint withdrawAmount (<= deposited amount). We then assert that after withdraw, address(c).balance decreased by withdrawAmount and owner (this) received that amount.

    receive() external payable {}

    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(depositAmount >= 0);
        // ensure we have Ether to deposit
        require(address(this).balance >= depositAmount);
        // deposit into c by invoking fallback: send plain ether with empty calldata
        // fallback is external payable and increments depositsCount
        c.fallback{value: depositAmount}();

        // read balances before withdraw
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Precondition for meaningful withdraw: withdrawAmount <= beforeC
        require(withdrawAmount <= beforeC);

        bool reverted;
        // call withdraw as owner (this contract is owner) and catch revert
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule: if the withdraw did not revert, c's balance decreased exactly by withdrawAmount and this contract's balance increased exactly by withdrawAmount.
        // If it reverted, balances are unchanged.
        assert((!reverted && beforeC - afterC == withdrawAmount && afterThis - beforeThis == withdrawAmount) || (reverted && beforeC == afterC && beforeThis == afterThis));
    }
}

