contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will try to send some ether to c (via fallback) and then attempt withdraw/withdrawAll.
    // Parameters:
    //  - sendAmount: amount of wei to send into c using fallback
    //  - withdrawAmount: amount to attempt to withdraw
    //  - doWithdrawAll: whether to call withdrawAll (true) or withdraw(withdrawAmount) (false)
    function run(uint sendAmount, uint withdrawAmount, bool doWithdrawAll) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance to fund c");

        // Record initial observable state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Send Ether to c's fallback to increase depositsCount and balance
        // This is a state-changing call and must be top-level.
        // If sendAmount is zero this still triggers fallback (fallback is payable) and increments depositsCount.
        (bool okSend,) = address(c).call{value: sendAmount}("");
        // call to fallback should not revert; if it does, we treat as failed send
        bool sendReverted = !okSend;

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Now attempt the withdraw or withdrawAll and record whether it reverts.
        bool withdrewReverted;
        uint balanceAfterWithdrawAttempt;
        if (doWithdrawAll) {
            try c.withdrawAll() {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        } else {
            try c.withdraw(withdrawAmount) {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        }
        balanceAfterWithdrawAttempt = address(c).balance;

        // General rule to assert:
        // 1) If the withdraw call succeeded (didn't revert) then msg.sender must have been owner of c — since in this harness
        //    msg.sender for calls to c is this InvMutTest contract, that means the owner getter must equal address(this).
        // 2) If the withdraw succeeded then c's balance decreased by at most withdrawAmount (for withdraw) or by the full previous balance (for withdrawAll).
        //    To express a general invariant without doing subtraction that can underflow inside assert, we rephrase:
        //    - For withdraw: balanceAfterWithdrawAttempt is either equal to afterBalance (if withdraw reverted or transferred 0)
        //      or strictly less than afterBalance (if some positive amount was transferred).
        //    - For withdrawAll: if it succeeded, balanceAfterWithdrawAttempt must be 0.
        // We combine these into one assertion relating owner, revert flag, and balances.

        address ownerAddr = c.owner();

        if (doWithdrawAll) {
            // If withdrawAll succeeded then owner must be this contract and balance is zero.
            // If withdrawAll reverted then either owner != this or other conditions; we assert implication for success only.
            assert(!(withdrewReverted == false) || (ownerAddr == address(this) && balanceAfterWithdrawAttempt == 0));
        } else {
            // For withdraw(amount): if it succeeded then owner must be this contract and balanceAfterWithdrawAttempt <= afterBalance.
            // and if withdrawAmount > 0 and succeeded then balanceAfterWithdrawAttempt < afterBalance.
            // We express that success implies owner==this and balanceAfterWithdrawAttempt <= afterBalance.
            assert(!(withdrewReverted == false) || (ownerAddr == address(this) && balanceAfterWithdrawAttempt <= afterBalance));
        }

        // Additionally, verify that fallback call (sending sendAmount) increments depositsCount by 1 when it didn't revert.
        // This ensures fallback behavior is observed: if send didn't revert then depositsCount increased by exactly 1.
        if (!sendReverted) {
            assert(afterDeposits == beforeDeposits + 1);
            assert(afterBalance == beforeBalance + sendAmount);
        }
    }

    // Allow this test contract to receive Ether when C withdraws to it.
    receive() external payable {}
 }

