    // NOTE: we must invoke a state-changing call on c directly as a top-level statement. C has no dedicated payable receive function, but its fallback is payable; calling a nonexistent function signature on c will route to fallback.
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Observe before state using only public getters
        uint beforeBalanceC = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Make a top-level external call to c that sends Ether and triggers fallback: call a nonexistent function selector so fallback executes.
        bool succeeded;
        // Using try/catch with a direct call to c by name: call a function that does not exist on C to route to fallback.
        // We declare an external function signature that is not present on C to force fallback; this is allowed as a direct call expression.
        try c.callNonexistent{value: amount}() {
            succeeded = true;
        } catch {
            succeeded = false;
        }

        // Observe after state
        uint afterBalanceC = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule: if the call reverted, balances and depositsCount unchanged; if it succeeded, depositsCount +=1 and C balance increased by amount.
        assert(
            (!succeeded && afterBalanceC == beforeBalanceC && afterDeposits == beforeDeposits)
            || (succeeded && afterDeposits == beforeDeposits + 1 && afterBalanceC == beforeBalanceC + amount)
        );
    }

    // Allow receiving Ether so this contract can be funded in the single transaction
    receive() external payable { }
}
